    const names=b(p.display_name||'Participante',()=>open('profile',{author:post.author_id}),'sf-name'),meta=el('div','sf-author');meta.append(names,el('span','sf-muted sf-handle','@'+(p.username||'participante')));const community=post.community_name||post.community?.name;if(community)meta.append(el('span','sf-pill','em '+community));
    const time=el('time','sf-time',relativeTime(post.created_at));time.dateTime=post.created_at;time.title=new Date(post.created_at).toLocaleString('pt-BR');
    const av=avatar(p);if(ctx.liveIds?.().has(post.author_id)){const wrap=el('div','sf-avatar-wrap sf-live');wrap.append(av,el('span','sf-live-badge','AO VIVO'));head.append(wrap);}else head.append(av);meta.append(el('span','sf-dot','·'),time);head.append(meta,menu(post));article.append(head);
