    if([...post.content].length>800){const details=el('details','sf-long-post');details.append(el('summary','','Ler artigo completo'),rich(post.content));article.append(rich(post.content.slice(0,300)+'…'),details);}else article.append(rich(post.content));
    if(post.poll){const pollBox=el('section','sf-poll');pollBox.setAttribute('aria-label','Enquete');const ended=Date.parse(post.poll.closes_at)<=Date.now(),total=(post.poll.votes||[]).reduce((sum,v)=>sum+Number(v.total),0);for(const [index,option]of post.poll.options.entries()){const votes=Number(post.poll.votes?.find(v=>v.option_index===index)?.total||0),voted=post.poll.my_vote!==null&&post.poll.my_vote!==undefined;const choose=b(option+(voted||ended?' · '+votes+' ('+(total?Math.round(votes/total*100):0)+'%)':''),async()=>{await checked(state().db.from('social_poll_votes').insert({post_id:post.id,user_id:uid,option_index:index}));if(root.isConnected&&!root.hidden)open(scope,{author,parent,query});});choose.disabled=ended||voted;choose.setAttribute('aria-pressed',String(post.poll.my_vote===index));pollBox.append(choose);}pollBox.append(el('small','sf-muted',total+' votos · '+(ended?'Encerrada':'Encerra '+relativeTime(post.poll.closes_at))));article.append(pollBox);}
    const firstLink=post.content.match(/https:\/\/[^\s<>]+/)?.[0];if(firstLink){try{const url=new URL(firstLink),preview=el('a','link-preview');preview.href=url.href;preview.target='_blank';preview.rel='noopener noreferrer';preview.append(el('strong','',url.hostname),el('span','sf-muted','Abrir link'));article.append(preview);import('./link-preview.js').then(module=>module.enhanceLinkPreview(preview,url,state().db)).catch(()=>{});}catch{}}
